/**
 * Golden-master tests for src/lib/slugify.ts.
 *
 * These freeze the THREE pipeline slug behaviors bit-for-bit. Stored slugs in
 * `entities` were generated by these exact rules; slugs are URL identity and
 * the ingest dedup key for CIF-less rows, so ANY change here re-keys existing
 * entities. If a test fails after editing slugify.ts, you are changing entity
 * identity: every stored slug would have to be re-keyed.
 *
 * Consolidation verified equivalent to the historical per-script
 * implementations across 519,228 real entity names on 2026-06-10.
 */
import { describe, expect, it } from "vitest";
import { slugify, slugifyContracts, slugifyGrants } from "../../src/lib/slugify";

describe("shared basics (all variants)", () => {
  const cases: [string, string][] = [
    ["Fundació Privada Catalana", "FUNDACIO-PRIVADA-CATALANA"],
    ["  L'Associació — Núm. 3  ", "L-ASSOCIACIO-NUM-3"],
    ["CONSTRUCCIONS GIRONA, S.L.", "CONSTRUCCIONS-GIRONA-SL"],
    ["EMPRESA EXEMPLE, S.A.U.", "EMPRESA-EXEMPLE-SAU"],
    ["COOPERATIVA DEL CAMP S.C.C.L.", "COOPERATIVA-DEL-CAMP-SCCL"],
    ["ROSTISSERIA EXEMPLE S.C.P.", "ROSTISSERIA-EXEMPLE-SCP"],
  ];
  for (const [name, expected] of cases) {
    it(`"${name}" → ${expected}`, () => {
      expect(slugifyGrants(name)).toBe(expected);
      expect(slugifyContracts(name)).toBe(expected);
      expect(slugify(name)).toBe(expected);
    });
  }
});

describe("slugifyGrants — frozen grants-pipeline behavior (dotted suffixes only)", () => {
  it("does NOT merge space-separated corporate suffixes", () => {
    expect(slugifyGrants("FLUMOTION SERVICES S A")).toBe("FLUMOTION-SERVICES-S-A");
    expect(slugifyGrants("ACCESIA FINANCE S L")).toBe("ACCESIA-FINANCE-S-L");
    expect(slugifyGrants("ROSTISSERIA CABANYES S C P")).toBe("ROSTISSERIA-CABANYES-S-C-P");
  });
  it("does NOT expand institutional abbreviations", () => {
    expect(slugifyGrants("ASSOC. CA LA DONA")).toBe("ASSOC-CA-LA-DONA");
    expect(slugifyGrants("FUND. PRIV. CASA AMERICA")).toBe("FUND-PRIV-CASA-AMERICA");
    expect(slugifyGrants("INST. D'HUMANITATS DE BCN")).toBe("INST-D-HUMANITATS-DE-BCN");
  });
});

describe("slugifyContracts — frozen contracts-pipeline behavior (dotted + spaced suffixes)", () => {
  it("merges space-separated corporate suffixes", () => {
    expect(slugifyContracts("FLUMOTION SERVICES S A")).toBe("FLUMOTION-SERVICES-SA");
    expect(slugifyContracts("ACCESIA FINANCE S L")).toBe("ACCESIA-FINANCE-SL");
    expect(slugifyContracts("EMPRESA EXEMPLE S A U")).toBe("EMPRESA-EXEMPLE-SAU");
    expect(slugifyContracts("ROSTISSERIA CABANYES S C P")).toBe("ROSTISSERIA-CABANYES-SCP");
  });
  it("does NOT expand institutional abbreviations", () => {
    expect(slugifyContracts("ASSOC. CA LA DONA")).toBe("ASSOC-CA-LA-DONA");
    expect(slugifyContracts("FUND. PRIV. CASA AMERICA")).toBe("FUND-PRIV-CASA-AMERICA");
  });
});

describe("slugify — frozen institutional behavior (abbreviations + dotted suffixes)", () => {
  it("expands institutional abbreviations", () => {
    expect(slugify("AJUNT. DE GIRONA")).toBe("AJUNTAMENT-DE-GIRONA");
    expect(slugify("AJ. DE LLEIDA")).toBe("AJUNTAMENT-DE-LLEIDA");
    expect(slugify("DIPUT. DE BARCELONA")).toBe("DIPUTACIO-DE-BARCELONA");
    expect(slugify("FUND. PRIV. CASA AMERICA")).toBe("FUNDACIO-PRIV-CASA-AMERICA");
    expect(slugify("ASSOC. CA LA DONA")).toBe("ASSOCIACIO-CA-LA-DONA");
  });
  it("does NOT merge space-separated corporate suffixes", () => {
    expect(slugify("FLUMOTION SERVICES S A")).toBe("FLUMOTION-SERVICES-S-A");
  });
  it("documents the known abbreviation false positives on company names", () => {
    // "CONS." here means Construccions, "INST" means instalación — the
    // expansion is semantically wrong but FROZEN: institutional sources only.
    expect(slugify("MAT. CONS. GRA DE FAJOL SL")).toBe("MAT-CONSORCI-GRA-DE-FAJOL-SL");
    expect(slugify("DISTRIB MONTAJE E INST HOSPITALARIA")).toBe(
      "DISTRIB-MONTAJE-E-INSTITUT-HOSPITALARIA"
    );
  });
});

describe("variant divergence is intentional and documented", () => {
  it("the three variants disagree exactly where the divergence was measured", () => {
    const name = "ASSOC. EXEMPLE S A";
    expect(slugifyGrants(name)).toBe("ASSOC-EXEMPLE-S-A");
    expect(slugifyContracts(name)).toBe("ASSOC-EXEMPLE-SA");
    expect(slugify(name)).toBe("ASSOCIACIO-EXEMPLE-S-A");
  });
});
